"use client";

import { useEffect, useState } from "react";

/* =======================
 * Types
 * ======================= */
type ItemEntity = {
  id: number;
  item_id: number;
  entity_type: string;
  raw_value: string;
  canonical_value: string;
  confidence: number;
  decision: "auto_accept" | "needs_review" | "rejected";
  extensions?: any;
  created_at: string;
};

type PageResp = {
  data: ItemEntity[];
  current_page: number;
  last_page: number;
};

/* =======================
 * Constants
 * ======================= */
const API_BASE =
  process.env.NEXT_PUBLIC_API_BASE_URL ?? "https://laravel.test:4430";

const REANALYZE_REASONS = [
  { value: "manual_reanalyze", label: "手動再解析" },
  { value: "policy_updated", label: "Policy 更新後" },
  { value: "assets_updated", label: "辞書更新後" },
  { value: "human_feedback", label: "人間レビュー反映" },
] as const;

type ReanalyzeReason = (typeof REANALYZE_REASONS)[number]["value"];

/* =======================
 * UI Parts
 * ======================= */
function DecisionBadge({ decision }: { decision: string }) {
  const color =
    decision === "auto_accept"
      ? "#16a34a"
      : decision === "needs_review"
        ? "#f59e0b"
        : "#dc2626";

  return (
    <span
      style={{
        padding: "2px 8px",
        borderRadius: 999,
        fontSize: 12,
        color: "white",
        backgroundColor: color,
      }}
    >
      {decision}
    </span>
  );
}

function ConfidenceBar({ value }: { value: number }) {
  const percent = Math.round(value * 100);
  const color =
    value >= 0.9 ? "#16a34a" : value >= 0.75 ? "#f59e0b" : "#dc2626";

  return (
    <div style={{ width: 90 }}>
      <div style={{ height: 6, background: "#eee", borderRadius: 4 }}>
        <div
          style={{
            width: `${percent}%`,
            height: "100%",
            background: color,
            borderRadius: 4,
          }}
        />
      </div>
      <div style={{ fontSize: 11, marginTop: 2 }}>{value.toFixed(3)}</div>
    </div>
  );
}

/* =======================
 * Page
 * ======================= */
export default function EntityReviewsPage() {
  const [rows, setRows] = useState<ItemEntity[]>([]);
  const [loading, setLoading] = useState(true);
  const [reason, setReason] = useState<ReanalyzeReason>("manual_reanalyze");

  async function load() {
    setLoading(true);
    const res = await fetch(`${API_BASE}/api/entity-reviews`, {
      credentials: "include",
    });
    const json: PageResp = await res.json();
    setRows(json.data ?? []);
    setLoading(false);
  }

  async function act(id: number, action: "approve" | "reject") {
    await fetch(`${API_BASE}/api/entity-reviews/${id}/${action}`, {
      method: "POST",
      credentials: "include",
    });
    await load();
  }

  async function reanalyze(id: number) {
    await fetch(`${API_BASE}/api/entity-reviews/${id}/reanalyze`, {
      method: "POST",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ reason }),
    });
    await load();
  }

  useEffect(() => {
    load();
  }, []);

  return (
    <div style={{ padding: 24, maxWidth: 1200, margin: "0 auto" }}>
      <h1 style={{ fontSize: 22, fontWeight: 700 }}>Entity Reviews</h1>

      <div style={{ marginTop: 12 }}>
        <label>再解析理由：</label>
        <select
          value={reason}
          onChange={(e) => setReason(e.target.value as ReanalyzeReason)}
        >
          {REANALYZE_REASONS.map((r) => (
            <option key={r.value} value={r.value}>
              {r.label}
            </option>
          ))}
        </select>
      </div>

      {loading ? (
        <p>Loading...</p>
      ) : (
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            marginTop: 16,
          }}
        >
          <thead>
            <tr>
              {[
                "ID",
                "Item",
                "Type",
                "Raw",
                "Canonical",
                "Confidence",
                "Decision",
                "Actions",
              ].map((h) => (
                <th
                  key={h}
                  style={{
                    borderBottom: "1px solid #ddd",
                    padding: 10,
                    textAlign: "left",
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>

          <tbody>
            {rows.map((row) => {
              const isNeedsReview = row.decision === "needs_review";

              return (
                <tr
                  key={row.id}
                  style={{
                    opacity: isNeedsReview ? 1 : 0.4,
                    background: isNeedsReview ? "transparent" : "#f7f7f7",
                  }}
                >
                  <td style={{ padding: 10 }}>{row.id}</td>
                  <td style={{ padding: 10 }}>{row.item_id}</td>
                  <td style={{ padding: 10 }}>{row.entity_type}</td>
                  <td style={{ padding: 10 }}>{row.raw_value}</td>
                  <td style={{ padding: 10 }}>{row.canonical_value}</td>
                  <td style={{ padding: 10 }}>
                    <ConfidenceBar value={row.confidence} />
                  </td>
                  <td style={{ padding: 10 }}>
                    <DecisionBadge decision={row.decision} />
                  </td>
                  <td style={{ padding: 10 }}>
                    <a
                      href={`/entity-audits/${row.id}`}
                      style={{ marginRight: 8 }}
                    >
                      History
                    </a>

                    {isNeedsReview && (
                      <>
                        <button onClick={() => act(row.id, "approve")}>
                          Approve
                        </button>{" "}
                        <button onClick={() => act(row.id, "reject")}>
                          Reject
                        </button>{" "}
                        <button onClick={() => reanalyze(row.id)}>
                          Reanalyze
                        </button>
                      </>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}
